23	func cleanLongDescription(ctx context.Context) string {
24		description := `Clean up Entire session data for the current HEAD commit.
25	
26	By default, cleans session state and shadow branches for the current HEAD:
27	  - Session state files (.git/entire-sessions/<session-id>.json)
28	  - Shadow branch (entire/<commit-hash>-<worktree-hash>)
29	
30	Use --all to clean all Entire session data across the repository:
31	  - All session state files (.git/entire-sessions/)
32	  - All shadow branches
33	  - Temporary files (.entire/tmp/)`
34	
35		s, err := settings.Load(ctx)
36		if err == nil && s.IsCheckpointsV2Enabled() {
37			description += fmt.Sprintf(`
38	  - Archived v2 full transcripts older than the configured %d-day retention window`, s.GetFullTranscriptGenerationRetentionDays())
39		}
40	
41		description += `
42	
43	Use --session <id> to clean a specific session only.
44	
45	Without --force, prompts for confirmation before deleting.
46	Use --dry-run to preview what would be deleted without prompting.`
47	
48		return description
49	}
