51	func newCleanCmd() *cobra.Command {
52		var forceFlag bool
53		var allFlag bool
54		var dryRunFlag bool
55		var sessionFlag string
56	
57		cmd := &cobra.Command{
58			Use:   "clean",
59			Short: "Clean up Entire session data",
60			Long:  cleanLongDescription(context.Background()),
61			RunE: func(cmd *cobra.Command, _ []string) error {
62				ctx := cmd.Context()
63	
64				// Validate mutually exclusive flags
65				if allFlag && sessionFlag != "" {
66					return errors.New("--all and --session cannot be used together")
67				}
68	
69				// Check if in git repository before initializing logging,
70				// to avoid creating .entire/logs in arbitrary directories.
71				if _, err := paths.WorktreeRoot(ctx); err != nil {
72					return errors.New("not a git repository")
73				}
74	
75				// Initialize logging
76				logging.SetLogLevelGetter(GetLogLevel)
77				if err := logging.Init(ctx, ""); err == nil {
78					defer logging.Close()
79				}
80	
81				if allFlag {
82					return runCleanAll(ctx, cmd, forceFlag, dryRunFlag)
83				}
84	
85				if sessionFlag != "" {
86					strat := GetStrategy(ctx)
87					return runCleanSession(ctx, cmd, strat, sessionFlag, forceFlag, dryRunFlag, "Clean", "cleaned")
88				}
89	
90				return runCleanCurrentHead(ctx, cmd, forceFlag, dryRunFlag)
91			},
92		}
93	
94		cmd.Flags().BoolVarP(&forceFlag, "force", "f", false, "Skip confirmation prompt and override active session guard")
95		cmd.Flags().BoolVarP(&allFlag, "all", "a", false, "Clean all session data across the repository")
96		cmd.Flags().BoolVarP(&dryRunFlag, "dry-run", "d", false, "Preview what would be deleted without deleting")
97		cmd.Flags().StringVar(&sessionFlag, "session", "", "Clean a specific session by ID")
98	
99		return cmd
100	}
