102	// runCleanCurrentHead cleans session data for the current HEAD commit.
103	func runCleanCurrentHead(ctx context.Context, cmd *cobra.Command, force, dryRun bool) error {
104		strat := GetStrategy(ctx)
105		w := cmd.OutOrStdout()
106	
107		// Dry-run: show what would be cleaned
108		if dryRun {
109			return previewCurrentHead(ctx, w)
110		}
111	
112		// Check for active sessions before cleaning
113		if !force {
114			activeSessions, err := activeSessionsOnCurrentHead(ctx)
115			if err != nil {
116				fmt.Fprintf(cmd.ErrOrStderr(), "Warning: could not check for active sessions: %v\n", err)
117				fmt.Fprintln(cmd.ErrOrStderr(), "Use --force to override.")
118				return nil
119			}
120			if len(activeSessions) > 0 {
121				fmt.Fprintln(cmd.ErrOrStderr(), "Active sessions detected on current HEAD:")
122				for _, s := range activeSessions {
123					fmt.Fprintf(cmd.ErrOrStderr(), "  %s (phase: %s)\n", s.SessionID, s.Phase)
124				}
125				fmt.Fprintln(cmd.ErrOrStderr(), "Use --force to override or wait for sessions to finish.")
126				return nil
127			}
128		}
129	
130		// Prompt for confirmation
131		if !force {
132			var confirmed bool
133	
134			form := NewAccessibleForm(
135				huh.NewGroup(
136					huh.NewConfirm().
137						Title("Clean session data for current HEAD?").
138						Value(&confirmed),
139				),
140			)
141	
142			if err := form.Run(); err != nil {
143				if errors.Is(err, huh.ErrUserAborted) {
144					return nil
145				}
146				return fmt.Errorf("failed to get confirmation: %w", err)
147			}
148	
149			if !confirmed {
150				return nil
151			}
152		}
153	
154		if err := strat.Reset(ctx, cmd.OutOrStdout(), cmd.ErrOrStderr()); err != nil {
155			return fmt.Errorf("clean failed: %w", err)
156		}
157	
158		return nil
159	}
