161	// previewCurrentHead shows what would be cleaned for the current HEAD.
162	func previewCurrentHead(ctx context.Context, w io.Writer) error {
163		repo, err := openRepository(ctx)
164		if err != nil {
165			return err
166		}
167	
168		head, err := repo.Head()
169		if err != nil {
170			return fmt.Errorf("failed to get HEAD: %w", err)
171		}
172	
173		worktreePath, err := paths.WorktreeRoot(ctx)
174		if err != nil {
175			return fmt.Errorf("failed to get worktree path: %w", err)
176		}
177		worktreeID, err := paths.GetWorktreeID(worktreePath)
178		if err != nil {
179			return fmt.Errorf("failed to get worktree ID: %w", err)
180		}
181	
182		shadowBranchName := checkpoint.ShadowBranchNameForCommit(head.Hash().String(), worktreeID)
183	
184		// Check if shadow branch exists
185		refName := plumbing.NewBranchReferenceName(shadowBranchName)
186		_, refErr := repo.Reference(refName, true)
187		hasShadowBranch := refErr == nil
188	
189		// Find sessions for this commit
190		strat := GetStrategy(ctx)
191		sessions, err := strat.FindSessionsForCommit(ctx, head.Hash().String())
192		if err != nil {
193			sessions = nil
194		}
195	
196		if !hasShadowBranch && len(sessions) == 0 {
197			fmt.Fprintln(w, "Nothing to clean for current HEAD.")
198			return nil
199		}
200	
201		fmt.Fprint(w, "Would clean the following items:\n\n")
202	
203		if len(sessions) > 0 {
204			fmt.Fprintf(w, "Session states (%d):\n", len(sessions))
205			for _, s := range sessions {
206				fmt.Fprintf(w, "  %s (checkpoints: %d)\n", s.SessionID, s.StepCount)
207			}
208			fmt.Fprintln(w)
209		}
210	
211		if hasShadowBranch {
212			fmt.Fprintf(w, "Shadow branch:\n  %s\n\n", shadowBranchName)
213		}
214	
215		fmt.Fprintln(w, "Run without --dry-run to clean these items.")
216		return nil
217	}
