219	// runCleanSession handles the --session flag: clean/reset a single session.
220	// actionVerb is the capitalized verb (e.g., "Clean" or "Reset") and pastVerb
221	// is the past tense (e.g., "cleaned" or "reset") used in user-facing messages.
222	func runCleanSession(ctx context.Context, cmd *cobra.Command, strat *strategy.ManualCommitStrategy, sessionID string, force, dryRun bool, actionVerb, pastVerb string) error {
223		// Verify the session exists
224		state, err := strategy.LoadSessionState(ctx, sessionID)
225		if err != nil {
226			return fmt.Errorf("failed to load session: %w", err)
227		}
228		if state == nil {
229			return fmt.Errorf("session not found: %s", sessionID)
230		}
231	
232		if dryRun {
233			w := cmd.OutOrStdout()
234			fmt.Fprintf(w, "Would %s session %s (phase: %s, checkpoints: %d)\n", strings.ToLower(actionVerb), sessionID, state.Phase, state.StepCount)
235			return nil
236		}
237	
238		if !force {
239			var confirmed bool
240	
241			title := fmt.Sprintf("%s session %s?", actionVerb, sessionID)
242			description := fmt.Sprintf("Phase: %s, Checkpoints: %d", state.Phase, state.StepCount)
243	
244			form := NewAccessibleForm(
245				huh.NewGroup(
246					huh.NewConfirm().
247						Title(title).
248						Description(description).
249						Value(&confirmed),
250				),
251			)
252	
253			if err := form.Run(); err != nil {
254				if errors.Is(err, huh.ErrUserAborted) {
255					return nil
256				}
257				return fmt.Errorf("failed to get confirmation: %w", err)
258			}
259	
260			if !confirmed {
261				return nil
262			}
263		}
264	
265		if err := strat.ResetSession(ctx, cmd.OutOrStdout(), cmd.ErrOrStderr(), sessionID); err != nil {
266			return fmt.Errorf("%s session failed: %w", strings.ToLower(actionVerb), err)
267		}
268	
269		fmt.Fprintf(cmd.OutOrStdout(), "Session %s has been %s. File changes remain in the working directory.\n", sessionID, pastVerb)
270		return nil
271	}
