273	// runCleanAll cleans all session data across the repository.
274	func runCleanAll(ctx context.Context, cmd *cobra.Command, force, dryRun bool) error {
275		s, err := settings.Load(ctx)
276		if err != nil {
277			fmt.Fprintf(cmd.ErrOrStderr(), "Warning: failed to load settings: %v\n", err)
278			s = &settings.EntireSettings{}
279		}
280	
281		// List all items (sessions, shadow branches) — not just orphaned ones
282		items, err := strategy.ListAllItems(ctx)
283		if err != nil {
284			return fmt.Errorf("failed to list items: %w", err)
285		}
286	
287		if s.IsCheckpointsV2Enabled() {
288			v2Items, warnings, err := strategy.ListEligibleV2Generations(ctx, s)
289			if err != nil {
290				return fmt.Errorf("failed to list v2 generations: %w", err)
291			}
292			items = append(items, v2Items...)
293			for _, warning := range warnings {
294				fmt.Fprintf(cmd.ErrOrStderr(), "Warning: %s\n", warning)
295			}
296		}
297	
298		// List temp files — skip active-session filter since --all deletes those sessions
299		tempFiles, err := listAllTempFiles(ctx)
300		if err != nil {
301			// Non-fatal: continue with other cleanup items
302			fmt.Fprintf(cmd.ErrOrStderr(), "Warning: failed to list temp files: %v\n", err)
303		}
304	
305		return runCleanAllWithItems(ctx, cmd, force, dryRun, items, tempFiles)
306	}
