331	// runCleanAllWithItems is the core logic for cleaning all items.
332	// Separated for testability — tests pass a cmd without a TTY and use force or dryRun to avoid prompts.
333	func runCleanAllWithItems(ctx context.Context, cmd *cobra.Command, force, dryRun bool, items []strategy.CleanupItem, tempFiles []string) error {
334		w := cmd.OutOrStdout()
335		errW := cmd.ErrOrStderr()
336		// Handle no items case
337		if len(items) == 0 && len(tempFiles) == 0 {
338			fmt.Fprintln(w, "No items to clean up.")
339			return nil
340		}
341	
342		// Group items by type for display
343		var branches, states, checkpoints, v2Generations []strategy.CleanupItem
344		for _, item := range items {
345			switch item.Type {
346			case strategy.CleanupTypeShadowBranch:
347				branches = append(branches, item)
348			case strategy.CleanupTypeSessionState:
349				states = append(states, item)
350			case strategy.CleanupTypeCheckpoint:
351				checkpoints = append(checkpoints, item)
352			case strategy.CleanupTypeV2Generation:
353				v2Generations = append(v2Generations, item)
354			}
355		}
356	
357		// Show preview when not in force mode
358		if !force || dryRun {
359			totalItems := len(items) + len(tempFiles)
360			fmt.Fprintf(w, "Found %d %s to clean:\n\n", totalItems, itemWord(totalItems))
361	
362			printSection(w, "Shadow branches", cleanupItemIDs(branches))
363			printSection(w, "Session states", cleanupItemIDs(states))
364			printSection(w, "Checkpoint metadata", cleanupItemIDs(checkpoints))
365			printSection(w, "Archived v2 generations", cleanupItemIDs(v2Generations))
366			printSection(w, "Temp files", tempFiles)
367	
368			if dryRun {
369				fmt.Fprintln(w, "Run without --dry-run to delete these items.")
370				return nil
371			}
372	
373			// Prompt for confirmation
374			var confirmed bool
375			form := NewAccessibleForm(
376				huh.NewGroup(
377					huh.NewConfirm().
378						Title(fmt.Sprintf("Delete %d %s?", totalItems, itemWord(totalItems))).
379						Value(&confirmed),
380				),
381			)
382			if err := form.Run(); err != nil {
383				if errors.Is(err, huh.ErrUserAborted) {
384					return nil
385				}
386				return fmt.Errorf("failed to get confirmation: %w", err)
387			}
388			if !confirmed {
389				return nil
390			}
391		}
392	
393		// Force mode - delete items
394		result, err := strategy.DeleteAllCleanupItems(ctx, items)
395		if err != nil {
396			return fmt.Errorf("failed to delete items: %w", err)
397		}
398	
399		// Delete temp files
400		deletedTempFiles, failedTempFiles := deleteTempFiles(ctx, tempFiles)
401	
402		// Report results
403		totalDeleted := len(result.ShadowBranches) + len(result.SessionStates) + len(result.Checkpoints) + len(result.V2Generations) + len(deletedTempFiles)
404		totalFailed := len(result.FailedBranches) + len(result.FailedStates) + len(result.FailedCheckpoints) + len(result.FailedV2Refs) + len(failedTempFiles)
405	
406		if totalDeleted > 0 {
407			fmt.Fprintf(w, "✓ Deleted %d %s:\n", totalDeleted, itemWord(totalDeleted))
408	
409			printResultSection(w, "Shadow branches", result.ShadowBranches)
410			printResultSection(w, "Session states", result.SessionStates)
411			printResultSection(w, "Checkpoints", result.Checkpoints)
412			printResultSection(w, "Archived v2 generations", result.V2Generations)
413	
414			printResultSection(w, "Temp files", deletedTempFiles)
415		}
416	
417		if totalFailed > 0 {
418			fmt.Fprintf(errW, "\nFailed to delete %d %s:\n", totalFailed, itemWord(totalFailed))
419	
420			printResultSection(errW, "Shadow branches", result.FailedBranches)
421			printResultSection(errW, "Session states", result.FailedStates)
422			printResultSection(errW, "Checkpoints", result.FailedCheckpoints)
423			printResultSection(errW, "Archived v2 generations", result.FailedV2Refs)
424	
425			if len(failedTempFiles) > 0 {
426				fmt.Fprintf(errW, "\nTemp files:\n")
427				for _, fe := range failedTempFiles {
428					fmt.Fprintf(errW, "  %s: %v\n", fe.File, fe.Err)
429				}
430			}
431	
432			return fmt.Errorf("failed to delete %d %s", totalFailed, itemWord(totalFailed))
433		}
434	
435		return nil
436	}
