447	// listAllTempFiles returns all files in .entire/tmp/ without filtering.
448	// Used by --all since those sessions are being deleted anyway.
449	func listAllTempFiles(ctx context.Context) ([]string, error) {
450		absDir, err := paths.AbsPath(ctx, paths.EntireTmpDir)
451		if err != nil {
452			return nil, fmt.Errorf("failed to resolve temp dir: %w", err)
453		}
454		root, err := os.OpenRoot(absDir)
455		if err != nil {
456			if os.IsNotExist(err) {
457				return nil, nil
458			}
459			return nil, fmt.Errorf("failed to open root: %w", err)
460		}
461		defer root.Close()
462	
463		var files []string
464		err = fs.WalkDir(root.FS(), ".", func(_ string, d fs.DirEntry, err error) error {
465			if err != nil {
466				return err
467			}
468			if d.IsDir() {
469				return nil
470			}
471			files = append(files, d.Name())
472			return nil
473		})
474		if os.IsNotExist(err) {
475			return nil, nil
476		}
477		if err != nil {
478			return nil, fmt.Errorf("failed to list temp dir: %w", err)
479		}
480		return files, nil
481	}
