483	// TempFileDeleteError contains a file name and the error that occurred during deletion.
484	type TempFileDeleteError struct {
485		File string
486		Err  error
487	}
488	
489	// deleteTempFiles removes all files in .entire/tmp/.
490	// Uses os.Root to ensure deletions are confined to the temp directory.
491	// Returns successfully deleted files and any failures with their error reasons.
492	func deleteTempFiles(ctx context.Context, files []string) (deleted []string, failed []TempFileDeleteError) {
493		absDir, err := paths.AbsPath(ctx, paths.EntireTmpDir)
494		if err != nil {
495			for _, file := range files {
496				failed = append(failed, TempFileDeleteError{File: file, Err: err})
497			}
498			return nil, failed
499		}
500		root, err := os.OpenRoot(absDir)
501		if err != nil {
502			for _, file := range files {
503				failed = append(failed, TempFileDeleteError{File: file, Err: err})
504			}
505			return nil, failed
506		}
507		defer root.Close()
508	
509		for _, file := range files {
510			if err := root.Remove(file); err != nil {
511				failed = append(failed, TempFileDeleteError{File: file, Err: err})
512			} else {
513				deleted = append(deleted, file)
514			}
515		}
516		return deleted, failed
517	}
