347	// ListEligibleV2Generations returns archived checkpoints v2 /full/* generations
348	// eligible for deletion based on the configured retention window, along with
349	// warnings for malformed generations that were skipped.
350	func ListEligibleV2Generations(ctx context.Context, s *settings.EntireSettings) ([]CleanupItem, []string, error) {
351		repo, err := OpenRepository(ctx)
352		if err != nil {
353			return nil, nil, fmt.Errorf("failed to open git repository: %w", err)
354		}
355	
356		store := checkpoint.NewV2GitStore(repo, "origin")
357		candidates, tempRefs, warnings, err := listArchivedV2GenerationCandidates(ctx, repo, store)
358		if err != nil {
359			return nil, nil, fmt.Errorf("failed to list archived generations: %w", err)
360		}
361		defer removeTempRefs(repo, tempRefs)
362	
363		cutoff := time.Now().AddDate(0, 0, -s.GetFullTranscriptGenerationRetentionDays())
364		cleanupItems := make([]CleanupItem, 0, len(candidates))
365	
366		for _, candidate := range candidates {
367			commitHash, treeHash, refErr := store.GetRefState(candidate.RefName)
368			if refErr != nil {
369				warnings = append(warnings, fmt.Sprintf("generation %s: cannot read ref: %v", candidate.Name, refErr))
370				continue
371			}
372	
373			gen, foundCheckpointTimes, timestampErr := store.ComputeGenerationTimestampsFromTrees(treeHash, nil)
374			if timestampErr != nil {
375				warnings = append(warnings, fmt.Sprintf("generation %s: failed to compute raw transcript timestamps: %v", candidate.Name, timestampErr))
376				continue
377			}
378			if !foundCheckpointTimes {
379				var genErr error
380				gen, genErr = store.ReadGeneration(treeHash)
381				if genErr != nil {
382					warnings = append(warnings, fmt.Sprintf("generation %s: failed to read generation.json: %v", candidate.Name, genErr))
383					continue
384				}
385			}
386	
387			hasOldest := !gen.OldestCheckpointAt.IsZero()
388			hasNewest := !gen.NewestCheckpointAt.IsZero()
389			switch {
390			case !hasOldest && !hasNewest:
391				warnings = append(warnings, fmt.Sprintf("generation %s: missing generation.json", candidate.Name))
392				continue
393			case hasOldest != hasNewest:
394				warnings = append(warnings, fmt.Sprintf("generation %s: incomplete generation.json", candidate.Name))
395				continue
396			case gen.OldestCheckpointAt.After(gen.NewestCheckpointAt):
397				warnings = append(warnings, fmt.Sprintf("generation %s: invalid timestamps", candidate.Name))
398				continue
399			}
400			if !gen.NewestCheckpointAt.Before(cutoff) {
401				continue
402			}
403	
404			refOID := candidate.RefOID
405			if refOID == "" {
406				refOID = commitHash.String()
407			}
408			cleanupItems = append(cleanupItems, CleanupItem{
409				Type:   CleanupTypeV2Generation,
