452		target, targetErr := remote.FetchURL(ctx)
453		if targetErr == nil && target != "" {
454			remoteRefs, remoteErr := listRemoteArchivedV2GenerationRefs(ctx, target)
455			if remoteErr != nil {
456				warnings = append(warnings, fmt.Sprintf("failed to list remote v2 generations: %v", remoteErr))
457			} else {
458				fetchTarget, fetchTargetErr := remote.ResolveFetchTarget(ctx, target)
459				if fetchTargetErr != nil {
460					warnings = append(warnings, fmt.Sprintf("failed to resolve remote for v2 generation fetch: %v", fetchTargetErr))
461				} else {
462					for name, remoteOID := range remoteRefs {
463						if candidate, ok := candidatesByName[name]; ok {
464							if candidate.RefOID == remoteOID {
465								candidate.HasRemote = true
466								candidatesByName[name] = candidate
467								continue
468							}
469							warnings = append(warnings, fmt.Sprintf("generation %s: local archived ref OID %s differs from remote OID %s; skipping cleanup", name, candidate.RefOID, remoteOID))
470							delete(candidatesByName, name)
471							continue
472						}
473						tempRef, fetchErr := fetchArchivedV2Generation(ctx, fetchTarget, name)
474						if fetchErr != nil {
475							warnings = append(warnings, fmt.Sprintf("generation %s: failed to fetch remote ref: %v", name, fetchErr))
476							continue
477						}
478						tempRefs = append(tempRefs, tempRef)
479						candidatesByName[name] = archivedV2GenerationCandidate{
480							Name:      name,
481							RefName:   tempRef,
482							RefOID:    remoteOID,
483							HasRemote: true,
484						}
485					}
486				}
487			}
488		}
489	
490		names := make([]string, 0, len(candidatesByName))
491		for name := range candidatesByName {
492			names = append(names, name)
493		}
494		sort.Strings(names)
495	
496		candidates := make([]archivedV2GenerationCandidate, 0, len(names))
497		for _, name := range names {
498			candidates = append(candidates, candidatesByName[name])
499		}
500		return candidates, tempRefs, warnings, nil
