251	func loadMergedSettings(settingsFileAbs, localSettingsFileAbs string) (*EntireSettings, error) {
252		// Load base settings
253		settings, err := loadFromFile(settingsFileAbs)
254		if err != nil {
255			return nil, fmt.Errorf("reading settings file: %w", err)
256		}
257	
258		// Apply local overrides if they exist
259		localData, err := os.ReadFile(localSettingsFileAbs) //nolint:gosec // path is from AbsPath or constant
260		if err != nil {
261			if !os.IsNotExist(err) {
262				return nil, fmt.Errorf("reading local settings file: %w", err)
263			}
264			// Local file doesn't exist, continue without overrides
265		} else {
266			if err := mergeJSON(settings, localData); err != nil {
267				return nil, fmt.Errorf("merging local settings: %w", err)
268			}
269		}
270	
271		// Re-validate after merge. Individual files are validated by loadFromFile,
272		// but mergeJSON patches fields independently and can produce combinations
273		// (e.g. model without provider when the local override sets only a model
274		// on top of a base with no provider) that neither file alone contained.
275		if err := settings.SummaryGeneration.Validate(); err != nil {
276			return nil, fmt.Errorf("merged settings invalid: %w", err)
277		}
278	
279		return settings, nil
280	}
